# name: recency_last_vs_first_example
# description: In 2+-example sets, for non-example targets strictly closer in size to the last-shown example than to the first (vs the reverse), yes-rate closer-to-last minus closer-to-first; observed above the null means people's size generalization favours the most recent example, which the span-based size mismatch (identical for every example) cannot produce (below means primacy).
def test_statistic(df):
    ns = df["number_set"].astype(str)
    sets = ns.unique()
    first = {s: int(s.split(",")[0]) for s in sets}
    last = {s: int(s.split(",")[-1]) for s in sets}
    k = {s: len(s.split(",")) for s in sets}
    exs = {s: set(int(v) for v in s.split(",")) for s in sets}
    f = ns.map(first).values; la = ns.map(last).values; kk = ns.map(k).values
    t = df["target"].astype(int).values
    ident = np.fromiter((tt in exs[s] for tt, s in zip(t, ns.values)), bool, len(t))
    base = (kk >= 2) & ~ident
    dl, dfst = np.abs(t - la), np.abs(t - f)
    cl, cf = base & (dl < dfst), base & (dfst < dl)
    y = df["rating"].astype(float).values
    if cl.sum() == 0 or cf.sum() == 0:
        return 0.0
    return float(y[cl].mean() - y[cf].mean())

# name: upward_vs_downward_outside_span
# description: Over all sets, yes-rate for targets 1-20 above the largest example minus targets 1-20 below the smallest example; observed above the null means people generalize upward (to larger numbers) more than the model's symmetric outside-span size mismatch predicts (below means a stronger downward bias than modelled).
def test_statistic(df):
    ns = df["number_set"].astype(str)
    sets = ns.unique()
    mx = {s: max(int(v) for v in s.split(",")) for s in sets}
    mn = {s: min(int(v) for v in s.split(",")) for s in sets}
    hi, lo = ns.map(mx).values, ns.map(mn).values
    t = df["target"].astype(int).values
    up = (t > hi) & (t - hi <= 20)
    dn = (t < lo) & (lo - t <= 20)
    y = df["rating"].astype(float).values
    if up.sum() == 0 or dn.sum() == 0:
        return 0.0
    return float(y[up].mean() - y[dn].mean())

# name: drift_step_curvature
# description: (yes-rate in trials 150-299 minus trials 0-149) minus (yes-rate in trials 300+ minus trials 150-299); observed above the null means the session drift toward "yes" is a front-loaded / saturating jump rather than the linear criterion relaxation the model assumes (below means the drift accelerates late).
def test_statistic(df):
    ti = df["trial_index"].astype(float).values
    y = df["rating"].astype(float).values
    a, b, c = ti < 150, (ti >= 150) & (ti < 300), ti >= 300
    if a.sum() == 0 or b.sum() == 0 or c.sum() == 0:
        return 0.0
    ma, mb, mc = y[a].mean(), y[b].mean(), y[c].mean()
    return float((mb - ma) - (mc - mb))

# name: outside_span_near_minus_far
# description: Among targets outside the example span, yes-rate for targets 1-10 beyond the nearest span edge minus targets 25-60 beyond it; observed above the null means people's generalization falls off with distance outside the span more steeply than the model's single magnitude tuning predicts (below means a flatter falloff than modelled).
def test_statistic(df):
    ns = df["number_set"].astype(str)
    sets = ns.unique()
    mx = {s: max(int(v) for v in s.split(",")) for s in sets}
    mn = {s: min(int(v) for v in s.split(",")) for s in sets}
    hi, lo = ns.map(mx).values, ns.map(mn).values
    t = df["target"].astype(int).values
    d = np.maximum(0, np.maximum(lo - t, t - hi))
    y = df["rating"].astype(float).values
    a = (d >= 1) & (d <= 10)
    b = (d >= 25) & (d <= 60)
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(y[a].mean() - y[b].mean())
